    uploadMessenger: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["MessengerUploadRequest"];
            };
        };
        responses: {
            /** @description 접수됨. 요약은 서버에서 진행 중이에요 */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["MessengerUpload"];
                };
            };
            /** @description 동의하지 않았거나(`CONSENT_REQUIRED`) 요청 값이 올바르지 않아요(`VALIDATION_FAILED`, 미래 날짜 · 60주 초과 포함) */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["AiConsentRequired"];
            /** @description 앞서 올린 대화를 아직 분석하고 있어요 (`UPLOAD_IN_PROGRESS`). `DONE`이나 `FAILED`가 된 뒤에 다시 올려요 */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description 요청이 너무 커요 (`PAYLOAD_TOO_LARGE`) */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description 이 API는 JSON만 받아요 (`IMAGES_NOT_ACCEPTED`). 스크린샷은 `POST /uploads/messenger/images`로 보내요 */
            415: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
    uploadMessengerImages: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "multipart/form-data": components["schemas"]["MessengerImageUploadRequest"];
            };
        };
        responses: {
            /** @description 접수됨. 서버에서 이미지를 읽고 요약하는 중이에요 */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["MessengerUpload"];
                };
            };
            /** @description 동의하지 않았거나(`CONSENT_REQUIRED`) 요청 값이 올바르지 않아요(`VALIDATION_FAILED`, 이미지가 없거나 100장 초과 포함) */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["AiConsentRequired"];
            /** @description 앞서 올린 대화를 아직 분석하고 있어요 (`UPLOAD_IN_PROGRESS`). `DONE`이나 `FAILED`가 된 뒤에 다시 올려요 */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description 한 장 5MB나 전체 50MB를 넘었어요 (`PAYLOAD_TOO_LARGE`). 나눠서 올려요 */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description JPEG · PNG · WebP가 아닌 파일이 있어요 (`UNSUPPORTED_IMAGE_TYPE`), 또는 `multipart/form-data`가 아니에요 */
            415: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
